#include <Arduino.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// CyberDeck hardware test: classic ESP32 (not ESP32-S3)
// OLED: SSD1306 128x64 I2C, SDA=GPIO13, SCL=GPIO27
// Button: GPIO14. BUTTON_MODE=0: native capacitive touch (T6).
//         BUTTON_MODE=1: external TTP223 digital output (active HIGH).

#ifndef BUTTON_MODE
#define BUTTON_MODE 1
#endif

static constexpr uint8_t OLED_SDA_PIN = 13;
static constexpr uint8_t OLED_SCL_PIN = 27;
static constexpr uint8_t BUTTON_PIN = 14;
static constexpr uint32_t SERIAL_BAUD = 115200;
static constexpr uint32_t DISPLAY_REFRESH_MS = 150;
static constexpr uint32_t SERIAL_REFRESH_MS = 500;
static constexpr uint32_t I2C_RETRY_MS = 2000;
static constexpr uint8_t SCREEN_WIDTH = 128;
static constexpr uint8_t SCREEN_HEIGHT = 64;

#if BUTTON_MODE == 0
static constexpr char BUTTON_MODE_NAME[] = "NATIVE TOUCH T6";
#else
static constexpr char BUTTON_MODE_NAME[] = "TTP223 DIGITAL";
#endif

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);

bool oledReady = false;
uint8_t oledAddress = 0;
bool buttonPressed = false;
bool previousButtonPressed = false;
uint32_t pressCount = 0;
uint32_t lastDisplayMs = 0;
uint32_t lastSerialMs = 0;
uint32_t lastI2cRetryMs = 0;
uint32_t bootMs = 0;

#if BUTTON_MODE == 0
uint16_t touchBaseline = 0;
uint16_t touchThreshold = 0;
uint16_t touchRaw = 0;
bool touchCalibrated = false;
#endif

uint8_t scanForOled() {
  bool found3C = false;
  bool found3D = false;

  for (uint8_t address = 0x08; address <= 0x77; ++address) {
    Wire.beginTransmission(address);
    const uint8_t error = Wire.endTransmission();
    if (error == 0) {
      Serial.printf("[I2C] Device found: 0x%02X\n", address);
      if (address == 0x3C) found3C = true;
      if (address == 0x3D) found3D = true;
    }
  }

  if (found3C) return 0x3C;
  if (found3D) return 0x3D;
  return 0;
}

bool initializeOled() {
  Serial.println("[OLED] Scanning I2C bus...");
  const uint8_t address = scanForOled();
  if (address == 0) {
    Serial.println("[OLED] No SSD1306 address (0x3C/0x3D) found.");
    oledReady = false;
    oledAddress = 0;
    return false;
  }

  if (!display.begin(SSD1306_SWITCHCAPVCC, address, true, false)) {
    Serial.println("[OLED] SSD1306 allocation/init failed.");
    oledReady = false;
    oledAddress = 0;
    return false;
  }

  oledAddress = address;
  oledReady = true;
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);
  display.setTextSize(1);
  display.setTextWrap(false);
  display.display();
  Serial.printf("[OLED] SSD1306 initialized at 0x%02X, 128x64.\n", oledAddress);
  return true;
}

#if BUTTON_MODE == 0
void calibrateTouch() {
  // Do not touch the GPIO14 pad while this one-time baseline is measured.
  Serial.println("[TOUCH] Calibration: keep GPIO14 pad untouched for about 1 second.");
  uint32_t sum = 0;
  constexpr uint8_t samples = 40;
  for (uint8_t i = 0; i < samples; ++i) {
    sum += touchRead(BUTTON_PIN);
    delay(25);
  }
  touchBaseline = static_cast<uint16_t>(sum / samples);
  touchThreshold = static_cast<uint16_t>(touchBaseline * 0.70f);
  if (touchThreshold < 5) touchThreshold = 5;
  touchRaw = touchRead(BUTTON_PIN);
  touchCalibrated = true;
  Serial.printf("[TOUCH] Baseline=%u, threshold=%u. Touch should lower the raw value.\n",
                touchBaseline, touchThreshold);
}
#endif

void updateButton() {
#if BUTTON_MODE == 0
  if (!touchCalibrated) return;

  touchRaw = touchRead(BUTTON_PIN);
  const uint16_t releaseThreshold = static_cast<uint16_t>(touchThreshold * 1.12f);

  if (!buttonPressed) {
    if (touchRaw < touchThreshold) buttonPressed = true;
  } else {
    if (touchRaw > releaseThreshold) buttonPressed = false;
  }

  // Slowly follow environmental drift only while the pad is not touched.
  if (!buttonPressed) {
    touchBaseline = static_cast<uint16_t>((touchBaseline * 99UL + touchRaw) / 100UL);
    touchThreshold = static_cast<uint16_t>(touchBaseline * 0.70f);
    if (touchThreshold < 5) touchThreshold = 5;
  }
#else
  // TTP223 modules normally drive OUT HIGH while touched.
  buttonPressed = (digitalRead(BUTTON_PIN) == HIGH);
#endif

  if (buttonPressed && !previousButtonPressed) {
    ++pressCount;
    Serial.printf("[BUTTON] Press #%lu\n", static_cast<unsigned long>(pressCount));
  }
  previousButtonPressed = buttonPressed;
}

void drawDisplay() {
  if (!oledReady) return;

  display.clearDisplay();
  display.fillRect(0, 0, SCREEN_WIDTH, 9, SSD1306_WHITE);
  display.setTextColor(SSD1306_BLACK);
  display.setCursor(2, 1);
  display.print(F("CYBERDECK / HW TEST"));

  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 12);
  display.print(F("OLED: OK  0x"));
  if (oledAddress < 0x10) display.print('0');
  display.print(oledAddress, HEX);

  display.setCursor(0, 21);
  display.print(F("I2C SDA:13 SCL:27"));

  display.setCursor(0, 30);
#if BUTTON_MODE == 0
  display.print(F("BTN: NATIVE TOUCH"));
#else
  display.print(F("BTN: TTP223 INPUT"));
#endif

  display.setCursor(0, 39);
  display.print(F("STATE: "));
  display.print(buttonPressed ? F("TOUCHED") : F("RELEASED"));

  display.setCursor(0, 48);
#if BUTTON_MODE == 0
  display.print(F("RAW:"));
  display.print(touchRaw);
  display.print(F(" THR:"));
  display.print(touchThreshold);
#else
  display.print(F("GPIO14: "));
  display.print(digitalRead(BUTTON_PIN) ? F("HIGH") : F("LOW"));
#endif

  display.setCursor(0, 57);
  display.print(F("PRESSES: "));
  display.print(pressCount);
  display.display();
}

void printStatus() {
  Serial.printf("[STATUS] OLED=%s", oledReady ? "OK" : "NOT FOUND");
  if (oledReady) Serial.printf(" (0x%02X)", oledAddress);
#if BUTTON_MODE == 0
  Serial.printf(" | mode=NATIVE_TOUCH | raw=%u | baseline=%u | threshold=%u",
                touchRaw, touchBaseline, touchThreshold);
#else
  Serial.printf(" | mode=TTP223 | GPIO14=%s", digitalRead(BUTTON_PIN) ? "HIGH" : "LOW");
#endif
  Serial.printf(" | state=%s | presses=%lu | uptime=%lus\n",
                buttonPressed ? "TOUCHED" : "RELEASED",
                static_cast<unsigned long>(pressCount),
                static_cast<unsigned long>((millis() - bootMs) / 1000UL));
}

void setup() {
  Serial.begin(SERIAL_BAUD);
  delay(250);
  bootMs = millis();

  Serial.println();
  Serial.println(F("===================================="));
  Serial.println(F(" CyberDeck ESP32 Hardware Test 1.0"));
  Serial.println(F(" Target: classic ESP32 (not S2/S3)"));
  Serial.printf(" OLED: SDA=GPIO%u, SCL=GPIO%u\n", OLED_SDA_PIN, OLED_SCL_PIN);
  Serial.printf(" Button: GPIO%u, mode=%s\n", BUTTON_PIN, BUTTON_MODE_NAME);
  Serial.println(F("===================================="));

#if BUTTON_MODE == 0
  calibrateTouch();
#else
  pinMode(BUTTON_PIN, INPUT);
#endif

  Wire.begin(OLED_SDA_PIN, OLED_SCL_PIN);
  Wire.setClock(100000);
  initializeOled();
  lastI2cRetryMs = millis();
  drawDisplay();
}

void loop() {
  const uint32_t now = millis();

  updateButton();

  if (!oledReady && now - lastI2cRetryMs >= I2C_RETRY_MS) {
    lastI2cRetryMs = now;
    initializeOled();
  }

  if (now - lastDisplayMs >= DISPLAY_REFRESH_MS) {
    lastDisplayMs = now;
    drawDisplay();
  }

  if (now - lastSerialMs >= SERIAL_REFRESH_MS) {
    lastSerialMs = now;
    printStatus();
  }

  delay(5);
}
